import { SessionData } from "@/lib/types";
import { encrypt, decrypt } from "./encrypt";
import { serialize } from "cookie";

export const createSession = (userData: SessionData) => {
  const sessionData = JSON.stringify(userData);
  const encryptedSessionData = encrypt(sessionData);

  return serialize("session", encryptedSessionData, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    maxAge: 60 * 60 * 24 * 7 * 8, // 2 months
    path: "/",
    sameSite: "lax",
  });
};

export const getSessionData = (encryptedSession: string): SessionData | null => {
  try {
    const decrypted = decrypt(encryptedSession);
    return JSON.parse(decrypted);
  } catch (error) {
    return null;
  }
};
